 if (any(type(x) is not int or x<=0 for x in [nv,nf,k,n,m,i]) or nv<4 or nf<4 or n!=nv+i or m<k
     or case['candidate_interior_node_tags']!=sorted(set(case['candidate_interior_node_tags']))
